import unittest
from candidate import filter_by_prefix


class TestFilterByPrefix(unittest.TestCase):
    def test_filter_by_prefix_normal_case_multiple_matches(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde', 'array'], 'a'), ['abc', 'array'])

    def test_filter_by_prefix_normal_case_single_match(self):
        self.assertEqual(filter_by_prefix(['hello', 'world', 'python'], 'h'), ['hello'])

    def test_filter_by_prefix_no_matches(self):
        self.assertEqual(filter_by_prefix(['bcd', 'cde', 'fgh'], 'a'), [])

    def test_filter_by_prefix_all_matches(self):
        self.assertEqual(filter_by_prefix(['apple', 'apricot', 'apply'], 'ap'), ['apple', 'apricot', 'apply'])

    def test_filter_by_prefix_empty_list(self):
        self.assertEqual(filter_by_prefix([], 'a'), [])

    def test_filter_by_prefix_empty_prefix_returns_all(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde'], ''), ['abc', 'bcd', 'cde'])

    def test_filter_by_prefix_empty_prefix_empty_list(self):
        self.assertEqual(filter_by_prefix([], ''), [])

    def test_filter_by_prefix_single_element_match(self):
        self.assertEqual(filter_by_prefix(['hello'], 'h'), ['hello'])

    def test_filter_by_prefix_single_element_no_match(self):
        self.assertEqual(filter_by_prefix(['hello'], 'z'), [])

    def test_filter_by_prefix_case_sensitive(self):
        self.assertEqual(filter_by_prefix(['Apple', 'apple', 'APPLE'], 'a'), ['apple'])

    def test_filter_by_prefix_case_sensitive_upper(self):
        self.assertEqual(filter_by_prefix(['Apple', 'apple', 'APPLE'], 'A'), ['Apple'])

    def test_filter_by_prefix_prefix_longer_than_string(self):
        self.assertEqual(filter_by_prefix(['ab'], 'abc'), [])

    def test_filter_by_prefix_prefix_equal_to_string(self):
        self.assertEqual(filter_by_prefix(['abc', 'abcd'], 'abc'), ['abc', 'abcd'])

    def test_filter_by_prefix_multiple_characters_prefix(self):
        self.assertEqual(filter_by_prefix(['banana', 'band', 'ball', 'blue'], 'ba'), ['banana', 'band', 'ball'])

    def test_filter_by_prefix_unicode_strings(self):
        self.assertEqual(filter_by_prefix(['héllo', 'hélice', 'world'], 'hél'), ['héllo', 'hélice'])

    def test_filter_by_prefix_with_numbers_in_strings(self):
        self.assertEqual(filter_by_prefix(['test1', 'test2', 'test3', 'other'], 'test'), ['test1', 'test2', 'test3'])

    def test_filter_by_prefix_whitespace_prefix(self):
        self.assertEqual(filter_by_prefix([' hello', 'world', ' world'], ' '), [' hello', ' world'])

    def test_filter_by_prefix_string_with_whitespace(self):
        self.assertEqual(filter_by_prefix([' hello', 'hello'], ' hello'), [' hello'])

    def test_filter_by_prefix_none_prefix_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(['abc', 'def'], None)

    def test_filter_by_prefix_none_strings_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(None, 'a')

    def test_filter_by_prefix_non_string_element_raises_attribute_error(self):
        with self.assertRaises(AttributeError):
            filter_by_prefix(['abc', 123, 'def'], 'a')

    def test_filter_by_prefix_non_string_prefix_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(['abc', 'def'], 123)

    def test_filter_by_prefix_tuple_of_strings(self):
        self.assertEqual(filter_by_prefix(('abc', 'bcd', 'cde'), 'a'), ['abc'])

    def test_filter_by_prefix_returns_list_type(self):
        result = filter_by_prefix(['abc', 'bcd'], 'a')
        self.assertIsInstance(result, list)

    def test_filter_by_prefix_does_not_modify_original_list(self):
        original = ['abc', 'bcd', 'cde']
        original_copy = original[:]
        filter_by_prefix(original, 'a')
        self.assertEqual(original, original_copy)

    def test_filter_by_prefix_preserves_order(self):
        self.assertEqual(filter_by_prefix(['zoo', 'apple', 'apply', 'ant'], 'a'), ['apple', 'apply', 'ant'])

    def test_filter_by_prefix_long_strings(self):
        long_prefix = 'a' * 100
        self.assertEqual(filter_by_prefix([long_prefix + 'b', 'c', long_prefix], long_prefix), [long_prefix + 'b', long_prefix])

    def test_filter_by_prefix_special_characters(self):
        self.assertEqual(filter_by_prefix(['!hello', '?world', '!bye'], '!'), ['!hello', '!bye'])

    def test_filter_by_prefix_digit_prefix(self):
        self.assertEqual(filter_by_prefix(['1abc', '2def', '3ghi'], '1'), ['1abc'])

    def test_filter_by_prefix_mixed_case_no_match(self):
        self.assertEqual(filter_by_prefix(['Hello', 'hello', 'HELLO'], 'Hello'), ['Hello'])

    def test_filter_by_prefix_prefix_is_full_string(self):
        self.assertEqual(filter_by_prefix(['exact', 'exacta', 'other'], 'exact'), ['exact', 'exacta'])


if __name__ == '__main__':
    unittest.main()
